sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float amplitude;
uniform float rotation;
uniform float frequency;
uniform float angle;
uniform float randomness;
uniform float curve;
uniform float transparentEdge;
uniform float opacity;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
float4 smp(float2 p, float tr) {
    return tr > 0.5 ? texT(p) : tex(p);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float e = pow(saturate(beat), curve);
    float t = time * frequency;
    float2 rnd = float2(vnoise(float2(t, 1.7)) - 0.5, vnoise(float2(t + 20.0, 4.1)) - 0.5) * 2.0;
    float2 dirv = float2(cos(radians(angle)), sin(radians(angle))) * (vnoise(float2(t, 8.0)) - 0.5) * 2.0;
    float2 off = mix(dirv, rnd, randomness) * amplitude * e;
    float rot = (vnoise(float2(t * 0.7 + 9.0, 2.0)) - 0.5) * 2.0 * radians(rotation) * e;
    float2 ctr = size * 0.5;
    float2 q = ctr + rot2(coord - ctr - off, -rot);
    return fin(c, smp(q, transparentEdge), opacity);
}
